  ('6f59f61a-d79a-48f1-8a0c-0360f2f9dd13', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b75f9224-e0f6-42a8-a3fc-e6749db8a4b1', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਨਰਿੰਦਰ ਸਿੰਘ ਕਪਾਨੀ ਵਿਗਿਆਨ ਦੇ ਨਾਲ-ਨਾਲ ਆਪਣੀਆਂ ਧਾਰਮਿਕ ਅਤੇ ਸੱਭਿਆਚਾਰਕ ਜੜ੍ਹਾਂ ਨਾਲ ਵੀ ਡੂੰਘੇ ਜੁੜੇ ਰਹੇ। ਉਹਨਾਂ ਨੇ AIFG ਈ. ਵਿੱਚ ਸਿੱਖ ਆਰਟ ਐਂਡ ਮਿਸ਼ਨਰੀ ਟਰੱਸਟ ਦੀ ਸਥਾਪਨਾ ਕੀਤੀ ਜਿਸ ਰਾਹੀਂ ਸਿੱਖੀ ਨਾਲ ਸੰਬੰਧਤ ਧਾਰਮਿਕ ਅਤੇ ਇਤਿਹਾਸਕ ਵਸਤਾਂ ਜਿਵੇਂ ਚਿੱਤਰ, ਪੇਂਟਿੰਗਜ਼, ਸਿੱਕੇ, ਭਾਂਡੇ ਆਦਿ ਨੂੰ ਸੰਭਾਲਣ ਦੇ ਬੇਸ਼ਕੀਮਤੀ ਯਤਨ ਕੀਤੇ ਗਏ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-144Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('628a09b9-04a1-437f-8ba5-ad663b439a21', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b75f9224-e0f6-42a8-a3fc-e6749db8a4b1', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਉਹਨਾਂ ਨੇ ਦੁਨੀਆ ਭਰ ਦੇ ਪ੍ਰਸਿੱਧ ਮਿਊਜ਼ੀਅਮਾਂ ਵਿੱਚ ਸਿੱਖ ਕਲਾ ਦੀਆਂ ਪ੍ਰਦਰਸ਼ਨੀਆਂ ਲਗਵਾਈਆਂ, ਜਿਸ ਨਾਲ ਪੰਜਾਬੀ ਵਿਰਾਸਤ ਨੂੰ ਨਵੀਂ ਪਛਾਣ ਮਿਲੀ। ਵਿਗਿਆਨਿਕ ਖੋਜਾਂ ਦੇ ਨਾਲ ਧਾਰਮਿਕ ਵਿਰਾਸਤ ਨੂੰ ਜਿਊਂਦਾ ਰੱਖਣ ਦੇ ਉਪਰਾਲਿਆਂ ਨੂੰ ਜਾਰੀ ਰੱਖਣਾ ਉਹਨਾਂ ਦੀ ਸ਼ਖਸੀਅਤ ਦਾ ਵਿਲੱਖਣ ਪਹਿਲੂ ਹੀ ਕਿਹਾ ਜਾ ਸਕਦਾ ਹੈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-144Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('c272c06b-aaa8-4eeb-aadb-dace79743755', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b75f9224-e0f6-42a8-a3fc-e6749db8a4b1', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਉਹਨਾਂ ਨੇ ਲੰਡਨ ਵਿੱਚ ਰਹਿੰਦਿਆਂ ਸਤਿੰਦਰ ਕੌਰ ਨਾਲ ਵਿਆਹ ਕਰਵਾਇਆ। ਉਹਨਾਂ ਦੀ ਪਤਨੀ ਨੇ ਵੀ ਸਿੱਖ-ਕਲਾ ਤੇ ਸੰਸਕ੍ਰਿਤੀ ਦੇ ਪ੍ਰਸਾਰ ਵਿੱਚ ਉਹਨਾਂ ਦਾ ਭਰਪੂਰ ਸਾਥ ਦਿੱਤਾ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-144Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('6b1c7877-f7a2-4247-ae42-aaedd089b6ca', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b75f9224-e0f6-42a8-a3fc-e6749db8a4b1', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪ੍ਰਸਿੱਧ ਅਮਰੀਕਨ ਵਪਾਰਕ ਰਸਾਲੇ 'ਫੋਰਚੂਨ' ਵੱਲੋਂ 2009 ਈ. ਵਿੱਚ '20ਵੀਂ ਸਦੀ ਦਾ ਛੁਪਿਆ ਨਾਇਕ' ਸਿਰਲੇਖ ਅਧੀਨ ਕਪਾਨੀ ਸਾਹਿਬ ਦੀਆਂ ਪ੍ਰਾਪਤੀਆਂ ਬਾਰੇ ਪ੍ਰਕਾਸ਼ਿਤ ਲੇਖ ਨੇ ਉਹਨਾਂ ਦੇ ਕੱਦ-ਬੁੱਤ ਨੂੰ ਹੋਰ ਬੁਲੰਦੀਆਂ ਬਖਸ਼ੀਆਂ। ਉਹਨਾਂ ਦੀਆਂ ਸੇਵਾਵਾਂ ਨੂੰ ਵਿਸ਼ਵ ਪੱਧਰ 'ਤੇ ਸਵੀਕਾਰਿਆ ਗਿਆ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-144Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('9aa8e2e9-4cef-40e7-9e83-f126483a24f3', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b75f9224-e0f6-42a8-a3fc-e6749db8a4b1', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$2008 ਈ: ਵਿੱਚ ਉਹਨਾਂ ਨੂੰ ਯੂਨੀਵਰਸਿਟੀ ਆਫ ਕੈਲੀਫੋਰਨੀਆ ਸਾਂਤਾ ਕਰੂਜ਼ ਵਿਗਿਆਨਿਕ ਅਤੇ ਅਕਾਦਮਿਕ ਪ੍ਰਾਪਤੀਆਂ ਲਈ 'ਫੀਅਟ ਲਕਸ ਸਨਮਾਨ' ਨਾਲ ਨਿਵਾਜਿਆ ਗਿਆ। 2011 ਈ. ਵਿੱਚ ਉਹਨਾਂ ਨੂੰ ਅਮਰੀਕਾ ਦੀ ਨੈਸ਼ਨਲ ਇਨਵੈਂਟਰ ਕਾਊਂਸਲ ਦੇ ਮੈਂਬਰ ਵਜੋਂ ਨਿਯੁਕਤ ਕੀਤਾ ਗਿਆ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-144Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('e5a3e863-bce5-49b3-9c39-6b32962383c8', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b75f9224-e0f6-42a8-a3fc-e6749db8a4b1', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਪਾਨੀ ਕੇਵਲ ਖੋਜੀ ਹੀ ਨਹੀਂ ਰਹੇ, ਸਗੋਂ ਉਹਨਾਂ ਨੇ ਆਪਣੀ ਖੋਜ ਨੂੰ ਸਮਾਜ ਤੱਕ ਪਹੁੰਚਾਉਣ ਲਈ ਅਹਿਮ ਕਦਮ ਚੁੱਕੇ। ਉਹਨਾਂ ਨੇ ਸਟੈਨਫੋਰਡ ਯੂਨੀਵਰਸਿਟੀ ਅਤੇ ਯੂਨੀਵਰਸਿਟੀ ਆਫ ਕੈਲੀਫੋਰਨੀਆ ਸਾਂਤਾ ਕਰੂਜ਼ ਵਿੱਚ ਵਿਦਿਆਰਥੀਆਂ ਨੂੰ ਪੜ੍ਹਾਇਆ ਅਤੇ ਖੋਜ ਸੰਸਥਾਵਾਂ ਸਥਾਪਿਤ ਕੀਤੀਆਂ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-144Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
