  ('dccb62c0-915f-4659-87bc-f5c777577a55', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b75f9224-e0f6-42a8-a3fc-e6749db8a4b1', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਉਹਨਾਂ ਨੇ ਕਈ ਹਾਈ-ਟੈੱਕ ਕੰਪਨੀਆਂ ਸਥਾਪਿਤ ਕੀਤੀਆਂ ਜੋ ਫਾਈਬਰ ਆਪਟਿਕਸ ਦੀ ਵਰਤੋਂ ਨੂੰ ਵਪਾਰਕ ਜਗਤ ਵਿੱਚ ਲੈ ਕੇ ਆਈਆਂ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-144Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('3afbc716-4a6e-4509-86e2-6e72a57b71f1', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b75f9224-e0f6-42a8-a3fc-e6749db8a4b1', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਨਰਿੰਦਰ ਸਿੰਘ ਕਪਾਨੀ ਵਿਗਿਆਨ ਦੇ ਨਾਲ-ਨਾਲ ਆਪਣੀਆਂ ਧਾਰਮਿਕ ਅਤੇ ਸੱਭਿਆਚਾਰਕ ਜੜ੍ਹਾਂ ਨਾਲ ਵੀ ਡੂੰਘੇ ਜੁੜੇ ਰਹੇ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-144Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('70c0dc69-9331-4e7d-aaec-a7ebdd013562', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b75f9224-e0f6-42a8-a3fc-e6749db8a4b1', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਉਹਨਾਂ ਨੇ AIFG ਈ. ਵਿੱਚ ਸਿੱਖ ਆਰਟ ਐਂਡ ਮਿਸ਼ਨਰੀ ਟਰੱਸਟ ਦੀ ਸਥਾਪਨਾ ਕੀਤੀ ਜਿਸ ਰਾਹੀਂ ਸਿੱਖੀ ਨਾਲ ਸੰਬੰਧਤ ਧਾਰਮਿਕ ਅਤੇ ਇਤਿਹਾਸਕ ਵਸਤਾਂ ਜਿਵੇਂ ਚਿੱਤਰ, ਪੇਂਟਿੰਗਜ਼, ਸਿੱਕੇ, ਭਾਂਡੇ ਆਦਿ ਨੂੰ ਸੰਭਾਲਣ ਦੇ ਬੇਸ਼ਕੀਮਤੀ ਯਤਨ ਕੀਤੇ ਗਏ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-144Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('02a8a32b-c2b3-4c85-9d81-c21fb4c7c6da', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b75f9224-e0f6-42a8-a3fc-e6749db8a4b1', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਉਹਨਾਂ ਨੇ ਦੁਨੀਆ ਭਰ ਦੇ ਪ੍ਰਸਿੱਧ ਮਿਊਜ਼ੀਅਮਾਂ ਵਿੱਚ ਸਿੱਖ ਕਲਾ ਦੀਆਂ ਪ੍ਰਦਰਸ਼ਨੀਆਂ ਲਗਵਾਈਆਂ, ਜਿਸ ਨਾਲ ਪੰਜਾਬੀ ਵਿਰਾਸਤ ਨੂੰ ਨਵੀਂ ਪਛਾਣ ਮਿਲੀ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-144Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('969da136-2d2b-447b-8c55-42c339ccc0c5', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b75f9224-e0f6-42a8-a3fc-e6749db8a4b1', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਉਹਨਾਂ ਨੇ ਲੰਡਨ ਵਿੱਚ ਰਹਿੰਦਿਆਂ ਸਤਿੰਦਰ ਕੌਰ ਨਾਲ ਵਿਆਹ ਕਰਵਾਇਆ। ਉਹਨਾਂ ਦੀ ਪਤਨੀ ਨੇ ਵੀ ਸਿੱਖ-ਕਲਾ ਤੇ ਸੰਸਕ੍ਰਿਤੀ ਦੇ ਪ੍ਰਸਾਰ ਵਿੱਚ ਉਹਨਾਂ ਦਾ ਭਰਪੂਰ ਸਾਥ ਦਿੱਤਾ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-144Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('4c76a9e0-d07a-438e-b9dc-643f7cace573', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b75f9224-e0f6-42a8-a3fc-e6749db8a4b1', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪ੍ਰਸਿੱਧ ਅਮਰੀਕਨ ਵਪਾਰਕ ਰਸਾਲੇ 'ਫੋਰਚੂਨ' ਵੱਲੋਂ 2009 ਈ. ਵਿੱਚ '20ਵੀਂ ਸਦੀ ਦਾ ਛੁਪਿਆ ਨਾਇਕ' ਸਿਰਲੇਖ ਅਧੀਨ ਕਪਾਨੀ ਸਾਹਿਬ ਦੀਆਂ ਪ੍ਰਾਪਤੀਆਂ ਬਾਰੇ ਪ੍ਰਕਾਸ਼ਿਤ ਲੇਖ ਨੇ ਉਹਨਾਂ ਦੇ ਕੱਦ-ਬੁੱਤ ਨੂੰ ਹੋਰ ਬੁਲੰਦੀਆਂ ਬਖਸ਼ੀਆਂ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-144Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('566f2811-4230-4d30-bca2-9cbbdb4d0e00', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b75f9224-e0f6-42a8-a3fc-e6749db8a4b1', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$2008 ਈ: ਵਿੱਚ ਉਹਨਾਂ ਨੂੰ ਯੂਨੀਵਰਸਿਟੀ ਆਫ ਕੈਲੀਫੋਰਨੀਆ ਸਾਂਤਾ ਕਰੂਜ਼ ਵਿਗਿਆਨਿਕ ਅਤੇ ਅਕਾਦਮਿਕ ਪ੍ਰਾਪਤੀਆਂ ਲਈ 'ਫੀਅਟ ਲਕਸ ਸਨਮਾਨ' ਨਾਲ ਨਿਵਾਜਿਆ ਗਿਆ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-144Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('5d62890b-7541-4c06-8556-ee109ae5dc55', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b75f9224-e0f6-42a8-a3fc-e6749db8a4b1', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$2011 ਈ. ਵਿੱਚ ਉਹਨਾਂ ਨੂੰ ਅਮਰੀਕਾ ਦੀ ਨੈਸ਼ਨਲ ਇਨਵੈਂਟਰ ਕਾਊਂਸਲ ਦੇ ਮੈਂਬਰ ਵਜੋਂ ਨਿਯੁਕਤ ਕੀਤਾ ਗਿਆ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-144Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('cad948d2-4bc3-46e3-a994-4ff5be649ec8', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b75f9224-e0f6-42a8-a3fc-e6749db8a4b1', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਪਾਨੀ ਕੇਵਲ ਖੋਜੀ ਹੀ ਨਹੀਂ ਰਹੇ, ਸਗੋਂ ਉਹਨਾਂ ਨੇ ਆਪਣੀ ਖੋਜ ਨੂੰ ਸਮਾਜ ਤੱਕ ਪਹੁੰਚਾਉਣ ਲਈ ਅਹਿਮ ਕਦਮ ਚੁੱਕੇ। ਉਹਨਾਂ ਨੇ ਸਟੈਨਫੋਰਡ ਯੂਨੀਵਰਸਿਟੀ ਅਤੇ ਯੂਨੀਵਰਸਿਟੀ ਆਫ ਕੈਲੀਫੋਰਨੀਆ ਸਾਂਤਾ ਕਰੂਜ਼ ਵਿੱਚ ਵਿਦਿਆਰਥੀਆਂ ਨੂੰ ਪੜ੍ਹਾਇਆ ਅਤੇ ਖੋਜ ਸੰਸਥਾਵਾਂ ਸਥਾਪਿਤ ਕੀਤੀਆਂ। ਉਹਨਾਂ ਨੇ ਕਈ ਹਾਈ-ਟੈੱਕ ਕੰਪਨੀਆਂ ਸਥਾਪਿਤ ਕੀਤੀਆਂ ਜੋ ਫਾਈਬਰ ਆਪਟਿਕਸ ਦੀ ਵਰਤੋਂ ਨੂੰ ਵਪਾਰਕ ਜਗਤ ਵਿੱਚ ਲੈ ਕੇ ਆਈਆਂ। ਉਹ ਆਪਟੀਕਲ ਸੋਸਾਇਟੀ ਆਫ ਅਮਰੀਕਾ, ਬ੍ਰਿਟਿਸ਼ ਰੋਇਲ ਅਕੈਡਮੀ ਆਫ ਇੰਜੀਨੀਅਰਿੰਗ, ਅਮਰੀਕਨ ਐਸੋਸੀਏਸ਼ਨ ਫਾਰ ਐਡਵਾਂਸਮੈਂਟ ਆਫ ਸਾਇੰਸ ਵਰਗੀਆਂ ਸੰਸਥਾਵਾਂ ਦੇ ਮੈਂਬਰ ਰਹੇ। ਨਰਿੰਦਰ ਸਿੰਘ ਕਪਾਨੀ ਵਿਗਿਆਨ ਦੇ ਨਾਲ-ਨਾਲ ਆਪਣੀਆਂ ਧਾਰਮਿਕ ਅਤੇ ਸੱਭਿਆਚਾਰਕ ਜੜ੍ਹਾਂ ਨਾਲ ਵੀ ਡੂੰਘੇ ਜੁੜੇ ਰਹੇ। ਉਹਨਾਂ ਨੇ AIFG ਈ. ਵਿੱਚ ਸਿੱਖ ਆਰਟ ਐਂਡ ਮਿਸ਼ਨਰੀ ਟਰੱਸਟ ਦੀ ਸਥਾਪਨਾ ਕੀਤੀ ਜਿਸ ਰਾਹੀਂ ਸਿੱਖੀ ਨਾਲ ਸੰਬੰਧਤ ਧਾਰਮਿਕ ਅਤੇ ਇਤਿਹਾਸਕ ਵਸਤਾਂ ਜਿਵੇਂ ਚਿੱਤਰ, ਪੇਂਟਿੰਗਜ਼, ਸਿੱਕੇ, ਭਾਂਡੇ ਆਦਿ ਨੂੰ ਸੰਭਾਲਣ ਦੇ ਬੇਸ਼ਕੀਮਤੀ ਯਤਨ ਕੀਤੇ ਗਏ। ਉਹਨਾਂ ਨੇ ਦੁਨੀਆ ਭਰ ਦੇ ਪ੍ਰਸਿੱਧ ਮਿਊਜ਼ੀਅਮਾਂ ਵਿੱਚ ਸਿੱਖ ਕਲਾ ਦੀਆਂ ਪ੍ਰਦਰਸ਼ਨੀਆਂ ਲਗਵਾਈਆਂ, ਜਿਸ ਨਾਲ ਪੰਜਾਬੀ ਵਿਰਾਸਤ ਨੂੰ ਨਵੀਂ ਪਛਾਣ ਮਿਲੀ। ਵਿਗਿਆਨਿਕ ਖੋਜਾਂ ਦੇ ਨਾਲ ਧਾਰਮਿਕ ਵਿਰਾਸਤ ਨੂੰ ਜਿਊਂਦਾ ਰੱਖਣ ਦੇ ਉਪਰਾਲਿਆਂ ਨੂੰ ਜਾਰੀ ਰੱਖਣਾ ਉਹਨਾਂ ਦੀ ਸ਼ਖਸੀਅਤ ਦਾ ਵਿਲੱਖਣ ਪਹਿਲੂ ਹੀ ਕਿਹਾ ਜਾ ਸਕਦਾ ਹੈ। ਉਹਨਾਂ ਨੇ ਲੰਡਨ ਵਿੱਚ ਰਹਿੰਦਿਆਂ ਸਤਿੰਦਰ ਕੌਰ ਨਾਲ ਵਿਆਹ ਕਰਵਾਇਆ। ਉਹਨਾਂ ਦੀ ਪਤਨੀ ਨੇ ਵੀ ਸਿੱਖ-ਕਲਾ ਤੇ ਸੰਸਕ੍ਰਿਤੀ ਦੇ ਪ੍ਰਸਾਰ ਵਿੱਚ ਉਹਨਾਂ ਦਾ ਭਰਪੂਰ ਸਾਥ ਦਿੱਤਾ। ਪ੍ਰਸਿੱਧ ਅਮਰੀਕਨ ਵਪਾਰਕ ਰਸਾਲੇ 'ਫੋਰਚੂਨ' ਵੱਲੋਂ 2009 ਈ. ਵਿੱਚ '20ਵੀਂ ਸਦੀ ਦਾ ਛੁਪਿਆ ਨਾਇਕ' ਸਿਰਲੇਖ ਅਧੀਨ ਕਪਾਨੀ ਸਾਹਿਬ ਦੀਆਂ ਪ੍ਰਾਪਤੀਆਂ ਬਾਰੇ ਪ੍ਰਕਾਸ਼ਿਤ ਲੇਖ ਨੇ ਉਹਨਾਂ ਦੇ ਕੱਦ-ਬੁੱਤ ਨੂੰ ਹੋਰ ਬੁਲੰਦੀਆਂ ਬਖਸ਼ੀਆਂ। ਉਹਨਾਂ ਦੀਆਂ ਸੇਵਾਵਾਂ ਨੂੰ ਵਿਸ਼ਵ ਪੱਧਰ 'ਤੇ ਸਵੀਕਾਰਿਆ ਗਿਆ। 2008 ਈ: ਵਿੱਚ ਉਹਨਾਂ ਨੂੰ ਯੂਨੀਵਰਸਿਟੀ ਆਫ ਕੈਲੀਫੋਰਨੀਆ ਸਾਂਤਾ ਕਰੂਜ਼ ਵਿਗਿਆਨਿਕ ਅਤੇ ਅਕਾਦਮਿਕ ਪ੍ਰਾਪਤੀਆਂ ਲਈ 'ਫੀਅਟ ਲਕਸ ਸਨਮਾਨ' ਨਾਲ ਨਿਵਾਜਿਆ ਗਿਆ। 2011 ਈ. ਵਿੱਚ ਉਹਨਾਂ ਨੂੰ ਅਮਰੀਕਾ ਦੀ ਨੈਸ਼ਨਲ ਇਨਵੈਂਟਰ ਕਾਊਂਸਲ ਦੇ ਮੈਂਬਰ ਵਜੋਂ ਨਿਯੁਕਤ ਕੀਤਾ ਗਿਆ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-144Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('f8ff0599-d0c8-4e2c-ae18-476007b75a84', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b75f9224-e0f6-42a8-a3fc-e6749db8a4b1', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਰਾਤ ਦਾ ਹਨੇਰਾ ਸੀ। ਆਗਰਾ ਸ਼ਹਿਰ ਦੇ ਇੱਕ ਛੋਟੇ-ਜਿਹੇ ਕਮਰੇ ਵਿੱਚ ਇੱਕ ਮੁੰਡਾ ਆਪਣੇ ਖਿਆਲਾਂ ਦੇ ਰੰਗਲੇ ਅਕਾਸ਼ ਵਿੱਚ ਉੱਡ ਰਿਹਾ ਸੀ। ਸਕੂਲ ਦੇ ਅਧਿਆਪਕ ਨੇ ਕਿਹਾ ਸੀ ਕਿ ਰੌਸ਼ਨੀ ਨੂੰ ਕਿਸੇ ਮੋੜਦਾਰ ਨਲੀ ਵਿੱਚ ਕਾਬੂ ਨਹੀਂ ਕੀਤਾ ਜਾ ਸਕਦਾ ਪਰ ਉਸ ਮੁੰਡੇ ਦੀ ਜਿਗਿਆਸਾ ਅਜਿਹੀ ਸੀ ਕਿ ਉਸ ਨੇ ਇਹ ਗੱਲ ਸਵੀਕਾਰ ਨਹੀਂ ਕੀਤੀ। ਉਸ ਨੇ ਸੋਚਿਆ ਜੇ ਪਾਣੀ ਨਲੀ ਵਿੱਚ ਅਰਾਮ ਨਾਲ ਲੰਘ ਸਕਦਾ ਹੈ ਤਾਂ ਰੌਸ਼ਨੀ ਕਿਉਂ ਨਹੀਂ? ਇਹ ਮੁੰਡਾ ਸੀ ਨਰਿੰਦਰ ਸਿੰਘ ਕਪਾਨੀ, ਜਿਸ ਨੇ ਭਵਿੱਖ ਵਿੱਚ ਸਾਬਤ ਕਰ ਦਿੱਤਾ ਕਿ ਰੌਸ਼ਨੀ ਨੂੰ ਨਾ ਸਿਰਫ ਨਲੀ ਵਿੱਚ ਕਾਬੂ ਕੀਤਾ ਜਾ ਸਕਦਾ ਹੈ, ਸਗੋਂ ਇਸ ਨਾਲ ਮਨੁੱਖੀ ਸੰਸਾਰ ਦਾ ਚਿਹਰਾ ਵੀ ਬਦਲਿਆ ਜਾ ਸਕਦਾ ਹੈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-144Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('45a6647a-e2ef-4bf8-947c-cd39e8ac6d63', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b75f9224-e0f6-42a8-a3fc-e6749db8a4b1', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਨਰਿੰਦਰ ਸਿੰਘ ਕਪਾਨੀ ਦਾ ਜਨਮ 31 ਅਕਤੂਬਰ 1926 ਈ: ਨੂੰ ਪੰਜਾਬ ਦੇ ਮੋਗਾ ਜ਼ਿਲ੍ਹੇ ਵਿੱਚ ਹੋਇਆ। ਉਹ ਦੂਜਿਆਂ ਬੱਚਿਆਂ ਵਾਂਗ ਦਿਸਦੇ ਤਾਂ ਸਧਾਰਨ ਹੀ ਸਨ ਪਰ ਉਹਨਾਂ ਦੀ ਸੋਚ ਸਭ ਤੋਂ ਵੱਖਰੀ ਤੇ ਉੱਚੀ ਹੁੰਦੀ ਸੀ। ਉਹਨਾਂ ਦੇ ਮਨ ਅੰਦਰ ਸਦਾ ਕੁਝ ਨਾ ਕੁਝ ਨਵਾਂ ਖੋਜਣ ਦੀ ਇੱਛਾ ਪਨਪਦੀ ਰਹਿੰਦੀ ਸੀ। ਖਿਡੌਣਿਆਂ ਨਾਲ ਖੇਡਣ ਦੀ ਥਾਂ ਉਹ ਘੜੀਆਂ, ਬਲਬਾਂ ਜਾਂ ਕੱਚ ਦੇ ਟੁਕੜਿਆਂ ਨਾਲ ਨਵੇਂ-ਨਵੇਂ ਤਜਰਬੇ ਕਰਦੇ ਰਹਿੰਦੇ ਸਨ। ਉਹਨਾਂ ਨੇ ਆਪਣੀ ਮੁੱਢਲੀ ਵਿੱਦਿਆ ਦੇਹਰਾਦੂਨ ਦੇ ਮਨਮੋਹਕ ਪਹਾੜੀ ਖੇਤਰ ਵਿੱਚ ਰਹਿੰਦਿਆਂ ਪੂਰੀ ਕੀਤੀ। ਇਸ ਤੋਂ ਬਾਅਦ ਉਹਨਾਂ ਨੇ ਆਗਰਾ ਯੂਨੀਵਰਸਿਟੀ ਤੋਂ ਭੌਤਿਕ ਵਿਗਿਆਨ ਵਿੱਚ ਗ੍ਰੈਜੂਏਸ਼ਨ ਕੀਤੀ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-144Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('37391af9-f30e-43bc-818f-e4917baf2bd5', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b75f9224-e0f6-42a8-a3fc-e6749db8a4b1', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਉਹਨਾਂ ਦੀ ਪੜ੍ਹਾਈ ਇੱਥੇ ਹੀ ਨਹੀਂ ਰੁਕੀ। ਉਹ ਜ਼ਿੰਦਗੀ ਵਿੱਚ ਕੁਝ ਨਵਾਂ ਕਰਨ ਦੇ ਮਕਸਦ ਨਾਲ 1952 ਈ: ਵਿੱਚ ਭਾਰਤ ਤੋਂ ਲੰਡਨ ਚਲੇ ਗਏ। ਉੱਥੇ ਉਹਨਾਂ ਨੇ ਬ੍ਰਿਟਿਸ਼ ਵਿਗਿਆਨੀ ਹੈਰੋਲਡ ਹਾਪਕਿਨਸ ਨਾਲ ਕੰਮ ਕੀਤਾ। ਉਹਨਾਂ ਨੇ 1954 ਈ: ਵਿੱਚ ਪਹਿਲੀ ਵਾਰ ਫਾਈਬਰਾਂ ਦੇ ਇੱਕ ਬੰਡਲ ਰਾਹੀਂ ਚਿੱਤਰ ਸੰਚਾਰ ਕਰਨ ਦਾ ਪ੍ਰਯੋਗ ਕੀਤਾ। ਉਸ ਤਜਰਬੇ ਦੇ ਨਤੀਜੇ 2 ਜਨਵਰੀ, 1954 ਈ: ਇੱਕ ਬ੍ਰਿਟਿਸ਼ ਰਸਾਲੇ 'ਨੇਚਰ' ਵਿੱਚ ਪ੍ਰਕਾਸ਼ਿਤ ਹੋਏ। ਇਹ ਗੱਲ ਹੁਣ ਚਿੱਟੇ ਦਿਨ ਵਾਂਗ ਸਾਫ ਸੀ ਕਿ ਰੌਸ਼ਨੀ ਨੂੰ ਫਾਈਬਰ ਰਾਹੀਂ ਮੋੜ ਕੇ ਇੱਕ ਪਾਸੇ ਤੋਂ ਦੂਜੇ ਪਾਸੇ ਭੇਜਿਆ ਜਾ ਸਕਦਾ ਹੈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-144Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
