  ('885e60fd-0f4e-413e-ad58-f0b95e7e4d9d', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b75f9224-e0f6-42a8-a3fc-e6749db8a4b1', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਨਰਿੰਦਰ ਸਿੰਘ ਕਪਾਨੀ ਨੇ ਭਵਿੱਖ ਵਿੱਚ ਸਾਬਤ ਕਰ ਦਿੱਤਾ ਕਿ ਰੌਸ਼ਨੀ ਨੂੰ ਨਾ ਸਿਰਫ ਨਲੀ ਵਿੱਚ ਕਾਬੂ ਕੀਤਾ ਜਾ ਸਕਦਾ ਹੈ, ਸਗੋਂ ਇਸ ਨਾਲ ਮਨੁੱਖੀ ਸੰਸਾਰ ਦਾ ਚਿਹਰਾ ਵੀ ਬਦਲਿਆ ਜਾ ਸਕਦਾ ਹੈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-144Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 1, NULL),
