  ('19f0c549-19ce-46fa-8266-502e1198af39', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b75f9224-e0f6-42a8-a3fc-e6749db8a4b1', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਜਿਗਿਆਸਾ - ਜਾਣਨ ਦੀ ਇੱਛਾ (curiosity, eagerness to know), ਤਜਰਬਾ - ਪ੍ਰਯੋਗ, ਪਰਖ (experiment), ਪ੍ਰਕਾਸ਼ਿਤ - ਛਾਪਣਾ (published)Í$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-144Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 1, NULL),
  ('fbecdd43-6d9e-4dc9-b19a-3f90c7a918a4', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b75f9224-e0f6-42a8-a3fc-e6749db8a4b1', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਹ ਖੋਜ ਨਰਿੰਦਰ ਸਿੰਘ ਕਪਾਨੀ ਨੂੰ ਵਿਸ਼ਵ ਪੱਧਰ ਤੱਕ ਮਕਬੂਲ ਕਰਨ ਵਿੱਚ ਸਹਾਇਕ ਹੋਈ। ਇਹੋ ਤਜਰਬਾ ਅੱਗੇ ਚੱਲ ਕੇ 'ਫਾਈਬਰ ਆਪਟਿਕਸ' ਦੇ ਨਾਂ ਨਾਲ ਜਾਣਿਆ ਗਿਆ ਅਤੇ ਨਰਿੰਦਰ ਸਿੰਘ ਕਪਾਨੀ ਨੂੰ ਫਾਈਬਰ ਆਪਟਿਕਸ ਦਾ ਪਿਤਾਮਾ ਕਿਹਾ ਜਾਣ ਲੱਗਾ। ਉਹਨਾਂ ਨੇ AIEE ਈ: ਵਿੱਚ ਇੰਪੀਰੀਅਲ ਕਾਲਜ ਆਫ਼ ਸਾਇੰਸ ਐਂਡ ਟੈਕਨਾਲੋਜੀ ਲੰਦਨ ਵਿੱਚ ਡਾਕਟਰੇਟ ਦੀ ਪੜ੍ਹਾਈ ਪੂਰੀ ਕਰ ਕੇ ਆਪਣੀਆਂ ਖੋਜਾਂ ਦਾ ਘੇਰਾ ਹੋਰ ਵਸੀਹ ਕੀਤਾ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-144Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('9d8c0458-c501-4f6b-a27c-d9b8d60146f4', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b75f9224-e0f6-42a8-a3fc-e6749db8a4b1', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਈ: ਵਿੱਚ ਕਪਾਨੀ ਨੇ ਪਹਿਲੀ ਵਾਰ 'ਫਾਈਬਰ ਆਪਟਿਕਸ' ਸ਼ਬਦ ਦੀ ਵਰਤੋਂ ਕੀਤੀ ਅਤੇ ਇਸ ਖੇਤਰ ਦਾ ਪ੍ਰਸਾਰ ਕੀਤਾ। ਉਹਨਾਂ ਨੇ 'ਫਾਈਬਰ ਆਪਟਿਕਸ-ਸਿਧਾਂਤ ਅਤੇ ਵਰਤੋਂ' ਨਾਂ ਦੀ ਪਹਿਲੀ ਕਿਤਾਬ ਲਿਖੀ। ਇਹ ਕਿਤਾਬ ਦੁਨੀਆ ਭਰ ਦੇ ਵਿਦਿਆਰਥੀਆਂ, ਅਧਿਆਪਕਾਂ ਅਤੇ ਖੋਜੀ ਵਿਗਿਆਨੀਆਂ ਲਈ ਮਾਰਗ-ਦਰਸ਼ਕ ਬਣੀ। ਉਹ ਫਾਈਬਰ ਆਪਟਿਕਸ ਖੇਤਰ ਵਿੱਚ ਸਭ ਤੋਂ ਪ੍ਰਸਿੱਧ ਲੇਖਕ ਅਤੇ ਜਾਣੇ-ਪਛਾਣੇ ਵਿਗਿਆਨਕਾਂ ਵਿੱਚੋਂ ਇੱਕ ਬਣੇ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-144Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('c1282d8e-afa1-46e1-b896-81073d8548d7', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b75f9224-e0f6-42a8-a3fc-e6749db8a4b1', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਉਹਨਾਂ ਦੀ ਖੋਜ ਸਿਰਫ ਇੱਥੋਂ ਤੱਕ ਹੀ ਸੀਮਤ ਨਹੀਂ ਰਹੀ। ਕਪਾਨੀ ਨੇ ਰੌਸ਼ਨੀ ਅਧਾਰਿਤ ਟੈਲੀਕਾਮ, ਲੇਜ਼ਰ ਪ੍ਰਣਾਲੀਆਂ, ਜੀਵ ਵਿਗਿਆਨਿਕ ਯੰਤਰ, ਸੂਰਜੀ ਊਰਜਾ ਅਤੇ ਪ੍ਰਦੂਸ਼ਣ ਨਿਗਰਾਨੀ ਵਿੱਚ ਕੰਮ ਕੀਤਾ। ਫਾਈਬਰ ਆਪਟਿਕਸ ਦੀ ਖੋਜ ਨੇ ਮਨੁੱਖਤਾ ਲਈ ਨਵੇਂ ਯੁੱਗ ਦੀ ਸ਼ੁਰੂਆਤ ਕੀਤੀ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-144Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('914bee8c-9f9b-49bd-9a34-86f51617d39f', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b75f9224-e0f6-42a8-a3fc-e6749db8a4b1', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਟੈਲੀਫੋਨ ਅਤੇ ਇੰਟਰਨੈੱਟ ਦੇ ਖੇਤਰ ਵਿੱਚ ਇਸ ਖੋਜ ਨੇ ਦੁਨੀਆ ਵਿੱਚ ਦੂਰੀਆਂ ਨੂੰ ਮਿਟਾ ਦਿੱਤਾ। ਅੱਜ ਅਸੀਂ ਇੱਕ ਕਲਿੱਕ ਨਾਲ ਸੰਸਾਰ ਦੇ ਕਿਸੇ ਵੀ ਕੋਨੇ ਨਾਲ ਜੁੜ ਸਕਦੇ ਹਾਂ। ਚਿਕਿਤਸਾ ਅਤੇ ਮੈਡੀਕਲ ਖੇਤਰ ਵਿੱਚ ਐਂਡੋਸਕੋਪੀ ਵਰਗੀ ਤਕਨਾਲੋਜੀ ਫਾਈਬਰ ਆਪਟਿਕਸ ਕਰਕੇ ਹੀ ਸੰਭਵ ਹੋਈ। ਇਸੇ ਕਰਕੇ ਡਾਕਟਰ ਮਰੀਜ਼ ਦੀ ਸਰਜਰੀ ਕੀਤੇ ਬਿਨਾਂ ਉਸ ਦੇ ਅੰਦਰੂਨੀ ਅੰਗਾਂ ਦੀ ਜਾਂਚ ਆਸਾਨੀ ਨਾਲ ਕਰਨ ਲੱਗ ਪਏ ਹਨ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-144Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('0179e8c1-2664-47fd-bf75-0324b63d1bf3', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b75f9224-e0f6-42a8-a3fc-e6749db8a4b1', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਫੌਜ ਅਤੇ ਪੁਲਾੜੀ ਖੇਤਰ ਵਿੱਚ ਤਾਂ 'ਫਾਈਬਰ ਆਪਟਿਕਸ' ਦੀ ਵਰਤੋਂ ਨੇ ਸੁਰੱਖਿਆ ਪ੍ਰਣਾਲੀਆਂ ਨੂੰ ਕਈ ਗੁਣਾ ਤੇਜ਼ ਅਤੇ ਸੁਚਾਰੂ ਬਣਾ ਦਿੱਤਾ। ਮਕਬੂਲ - ਮੰਨਿਆ ਹੋਇਆ, ਪ੍ਰਸਿੱਧ, ਫਾਈਬਰ ਆਪਟਿਕਸ - ਰੌਸ਼ਨੀ ਨੂੰ ਬਰੀਕ ਕੱਚ/ਪਲਾਸਟਿਕ ਦੀ ਨਲੀ ਰਾਹੀਂ ਭੇਜਣ ਦੀ ਵਿਗਿਆਨਕ ਤਕਨੀਕ, ਝੋਲੀ ਵਿੱਚ ਪਾਈਆਂ - ਦਿੱਤੀਆਂ, ਯੋਗਦਾਨ ਦਿੱਤਾ, ਚਿਕਿਤਸਾ - ਇਲਾਜ, ਦਵਾਈ - ਥੈਰੇਪੀ, ਐਂਡੋਸਕੋਪੀ - ਅੰਦਰੂਨੀ ਅੰਗਾਂ ਦੀ ਜਾਂਚ ਕਰਨ ਦੀ ਤਕਨੀਕ, ਸੁਚਾਰੂ - ਠੀਕ ਤਰੀਕੇ ਨਾਲ, ਬਿਨਾਂ ਰੁਕਾਵਟ ਦੇ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-144Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
