  ('bbc30922-1b08-44ce-bb40-cbd9d906fc3d', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b75f9224-e0f6-42a8-a3fc-e6749db8a4b1', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਝੋਲੀ ਵਿੱਚ ਪਾਈਆਂ - ਦਿੱਤੀਆਂ, ਯੋਗਦਾਨ ਦਿੱਤਾ$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-144Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 1, NULL),
  ('7b72bf4e-e9b3-4e33-8710-a1aec5e30519', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b75f9224-e0f6-42a8-a3fc-e6749db8a4b1', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਚਿਕਿਤਸਾ - ਇਲਾਜ, ਦਵਾਈ - ਥੈਰੇਪੀ$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-144Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 1, NULL),
  ('d1f28739-e538-46a9-8f06-bdd09b748742', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b75f9224-e0f6-42a8-a3fc-e6749db8a4b1', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਪਾਨੀ ਕੇਵਲ ਖੋਜੀ ਹੀ ਨਹੀਂ ਰਹੇ, ਸਗੋਂ ਉਹਨਾਂ ਨੇ ਆਪਣੀ ਖੋਜ ਨੂੰ ਸਮਾਜ ਤੱਕ ਪਹੁੰਚਾਉਣ ਲਈ ਅਹਿਮ ਕਦਮ ਚੁੱਕੇ। ਉਹਨਾਂ ਨੇ ਸਟੈਨਫੋਰਡ ਯੂਨੀਵਰਸਿਟੀ ਅਤੇ ਯੂਨੀਵਰਸਿਟੀ ਆਫ ਕੈਲੀਫੋਰਨੀਆ ਸਾਂਤਾ ਕਰੂਜ਼ ਵਿੱਚ ਵਿਦਿਆਰਥੀਆਂ ਨੂੰ ਪੜ੍ਹਾਇਆ ਅਤੇ ਖੋਜ ਸੰਸਥਾਵਾਂ ਸਥਾਪਿਤ ਕੀਤੀਆਂ। ਉਹਨਾਂ ਨੇ ਕਈ ਹਾਈ-ਟੈੱਕ ਕੰਪਨੀਆਂ ਸਥਾਪਿਤ ਕੀਤੀਆਂ ਜੋ ਫਾਈਬਰ ਆਪਟਿਕਸ ਦੀ ਵਰਤੋਂ ਨੂੰ ਵਪਾਰਕ ਜਗਤ ਵਿੱਚ ਲੈ ਕੇ ਆਈਆਂ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-144Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('be362c7a-29de-4588-a85d-8a394e19c5f8', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b75f9224-e0f6-42a8-a3fc-e6749db8a4b1', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਉਹ ਆਪਟੀਕਲ ਸੋਸਾਇਟੀ ਆਫ ਅਮਰੀਕਾ, ਬ੍ਰਿਟਿਸ਼ ਰੋਇਲ ਅਕੈਡਮੀ ਆਫ ਇੰਜੀਨੀਅਰਿੰਗ, ਅਮਰੀਕਨ ਐਸੋਸੀਏਸ਼ਨ ਫਾਰ ਐਡਵਾਂਸਮੈਂਟ ਆਫ ਸਾਇੰਸ ਵਰਗੀਆਂ ਸੰਸਥਾਵਾਂ ਦੇ ਮੈਂਬਰ ਰਹੇ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-144Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('089ffefd-9ad2-4052-a60b-f4046b31fb3a', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b75f9224-e0f6-42a8-a3fc-e6749db8a4b1', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਨਰਿੰਦਰ ਸਿੰਘ ਕਪਾਨੀ ਵਿਗਿਆਨ ਦੇ ਨਾਲ-ਨਾਲ ਆਪਣੀਆਂ ਧਾਰਮਿਕ ਅਤੇ ਸੱਭਿਆਚਾਰਕ ਜੜ੍ਹਾਂ ਨਾਲ ਵੀ ਡੂੰਘੇ ਜੁੜੇ ਰਹੇ। ਉਹਨਾਂ ਨੇ AIFG ਈ. ਵਿੱਚ ਸਿੱਖ ਆਰਟ ਐਂਡ ਮਿਸ਼ਨਰੀ ਟਰੱਸਟ ਦੀ ਸਥਾਪਨਾ ਕੀਤੀ ਜਿਸ ਰਾਹੀਂ ਸਿੱਖੀ ਨਾਲ ਸੰਬੰਧਤ ਧਾਰਮਿਕ ਅਤੇ ਇਤਿਹਾਸਕ ਵਸਤਾਂ ਜਿਵੇਂ ਚਿੱਤਰ, ਪੇਂਟਿੰਗਜ਼, ਸਿੱਕੇ, ਭਾਂਡੇ ਆਦਿ ਨੂੰ ਸੰਭਾਲਣ ਦੇ ਬੇਸ਼ਕੀਮਤੀ ਯਤਨ ਕੀਤੇ ਗਏ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-144Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('65613376-ec49-4add-95a9-9955de39d3b2', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b75f9224-e0f6-42a8-a3fc-e6749db8a4b1', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਉਹਨਾਂ ਨੇ ਦੁਨੀਆ ਭਰ ਦੇ ਪ੍ਰਸਿੱਧ ਮਿਊਜ਼ੀਅਮਾਂ ਵਿੱਚ ਸਿੱਖ ਕਲਾ ਦੀਆਂ ਪ੍ਰਦਰਸ਼ਨੀਆਂ ਲਗਵਾਈਆਂ, ਜਿਸ ਨਾਲ ਪੰਜਾਬੀ ਵਿਰਾਸਤ ਨੂੰ ਨਵੀਂ ਪਛਾਣ ਮਿਲੀ। ਵਿਗਿਆਨਿਕ ਖੋਜਾਂ ਦੇ ਨਾਲ ਧਾਰਮਿਕ ਵਿਰਾਸਤ ਨੂੰ ਜਿਊਂਦਾ ਰੱਖਣ ਦੇ ਉਪਰਾਲਿਆਂ ਨੂੰ ਜਾਰੀ ਰੱਖਣਾ ਉਹਨਾਂ ਦੀ ਸ਼ਖਸੀਅਤ ਦਾ ਵਿਲੱਖਣ ਪਹਿਲੂ ਹੀ ਕਿਹਾ ਜਾ ਸਕਦਾ ਹੈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-144Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('2ebc31d7-220d-44e7-9a71-db6601d66282', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b75f9224-e0f6-42a8-a3fc-e6749db8a4b1', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਉਹਨਾਂ ਨੇ ਲੰਡਨ ਵਿੱਚ ਰਹਿੰਦਿਆਂ ਸਤਿੰਦਰ ਕੌਰ ਨਾਲ ਵਿਆਹ ਕਰਵਾਇਆ। ਉਹਨਾਂ ਦੀ ਪਤਨੀ ਨੇ ਵੀ ਸਿੱਖ-ਕਲਾ ਤੇ ਸੰਸਕ੍ਰਿਤੀ ਦੇ ਪ੍ਰਸਾਰ ਵਿੱਚ ਉਹਨਾਂ ਦਾ ਭਰਪੂਰ ਸਾਥ ਦਿੱਤਾ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-144Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('5ac51d3e-0cdb-4cc3-bfd8-06888e3cf0ae', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b75f9224-e0f6-42a8-a3fc-e6749db8a4b1', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪ੍ਰਸਿੱਧ ਅਮਰੀਕਨ ਵਪਾਰਕ ਰਸਾਲੇ 'ਫੋਰਚੂਨ' ਵੱਲੋਂ 2009 ਈ. ਵਿੱਚ '20ਵੀਂ ਸਦੀ ਦਾ ਛੁਪਿਆ ਨਾਇਕ' ਸਿਰਲੇਖ ਅਧੀਨ ਕਪਾਨੀ ਸਾਹਿਬ ਦੀਆਂ ਪ੍ਰਾਪਤੀਆਂ ਬਾਰੇ ਪ੍ਰਕਾਸ਼ਿਤ ਲੇਖ ਨੇ ਉਹਨਾਂ ਦੇ ਕੱਦ-ਬੁੱਤ ਨੂੰ ਹੋਰ ਬੁਲੰਦੀਆਂ ਬਖਸ਼ੀਆਂ। ਉਹਨਾਂ ਦੀਆਂ ਸੇਵਾਵਾਂ ਨੂੰ ਵਿਸ਼ਵ ਪੱਧਰ 'ਤੇ ਸਵੀਕਾਰਿਆ ਗਿਆ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-144Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('e17996e5-43a4-4a32-a53b-aea443367e47', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b75f9224-e0f6-42a8-a3fc-e6749db8a4b1', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$2008 ਈ: ਵਿੱਚ ਉਹਨਾਂ ਨੂੰ ਯੂਨੀਵਰਸਿਟੀ ਆਫ ਕੈਲੀਫੋਰਨੀਆ ਸਾਂਤਾ ਕਰੂਜ਼ ਵਿਗਿਆਨਿਕ ਅਤੇ ਅਕਾਦਮਿਕ ਪ੍ਰਾਪਤੀਆਂ ਲਈ 'ਫੀਅਟ ਲਕਸ ਸਨਮਾਨ' ਨਾਲ ਨਿਵਾਜਿਆ ਗਿਆ। 2011 ਈ. ਵਿੱਚ ਉਹਨਾਂ ਨੂੰ ਅਮਰੀਕਾ ਦੀ ਨੈਸ਼ਨਲ ਇਨਵੈਂਟਰ ਕਾਊਂਸਲ ਦੇ ਮੈਂਬਰ ਵਜੋਂ ਨਿਯੁਕਤ ਕੀਤਾ ਗਿਆ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-144Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('184aa159-79ea-4616-a0d4-e3856baa17fe', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b75f9224-e0f6-42a8-a3fc-e6749db8a4b1', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਪਾਨੀ ਕੇਵਲ ਖੋਜੀ ਹੀ ਨਹੀਂ ਰਹੇ, ਸਗੋਂ ਉਹਨਾਂ ਨੇ ਆਪਣੀ ਖੋਜ ਨੂੰ ਸਮਾਜ ਤੱਕ ਪਹੁੰਚਾਉਣ ਲਈ ਅਹਿਮ ਕਦਮ ਚੁੱਕੇ। ਉਹਨਾਂ ਨੇ ਸਟੈਨਫੋਰਡ ਯੂਨੀਵਰਸਿਟੀ ਅਤੇ ਯੂਨੀਵਰਸਿਟੀ ਆਫ ਕੈਲੀਫੋਰਨੀਆ ਸਾਂਤਾ ਕਰੂਜ਼ ਵਿੱਚ ਵਿਦਿਆਰਥੀਆਂ ਨੂੰ ਪੜ੍ਹਾਇਆ ਅਤੇ ਖੋਜ ਸੰਸਥਾਵਾਂ ਸਥਾਪਿਤ ਕੀਤੀਆਂ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-144Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('c9451f50-5cc8-4235-8608-a11177f63637', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b75f9224-e0f6-42a8-a3fc-e6749db8a4b1', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਉਹਨਾਂ ਨੇ ਕਈ ਹਾਈ-ਟੈੱਕ ਕੰਪਨੀਆਂ ਸਥਾਪਿਤ ਕੀਤੀਆਂ ਜੋ ਫਾਈਬਰ ਆਪਟਿਕਸ ਦੀ ਵਰਤੋਂ ਨੂੰ ਵਪਾਰਕ ਜਗਤ ਵਿੱਚ ਲੈ ਕੇ ਆਈਆਂ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-144Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('ad84d167-98d8-4fe4-99c3-48ffd98857e5', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b75f9224-e0f6-42a8-a3fc-e6749db8a4b1', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਨਰਿੰਦਰ ਸਿੰਘ ਕਪਾਨੀ ਵਿਗਿਆਨ ਦੇ ਨਾਲ-ਨਾਲ ਆਪਣੀਆਂ ਧਾਰਮਿਕ ਅਤੇ ਸੱਭਿਆਚਾਰਕ ਜੜ੍ਹਾਂ ਨਾਲ ਵੀ ਡੂੰਘੇ ਜੁੜੇ ਰਹੇ। ਉਹਨਾਂ ਨੇ AIFG ਈ. ਵਿੱਚ ਸਿੱਖ ਆਰਟ ਐਂਡ ਮਿਸ਼ਨਰੀ ਟਰੱਸਟ ਦੀ ਸਥਾਪਨਾ ਕੀਤੀ ਜਿਸ ਰਾਹੀਂ ਸਿੱਖੀ ਨਾਲ ਸੰਬੰਧਤ ਧਾਰਮਿਕ ਅਤੇ ਇਤਿਹਾਸਕ ਵਸਤਾਂ ਜਿਵੇਂ ਚਿੱਤਰ, ਪੇਂਟਿੰਗਜ਼, ਸਿੱਕੇ, ਭਾਂਡੇ ਆਦਿ ਨੂੰ ਸੰਭਾਲਣ ਦੇ ਬੇਸ਼ਕੀਮਤੀ ਯਤਨ ਕੀਤੇ ਗਏ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-144Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('78299f4b-c5ee-4840-975b-ed86af117593', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b75f9224-e0f6-42a8-a3fc-e6749db8a4b1', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਉਹਨਾਂ ਨੇ ਦੁਨੀਆ ਭਰ ਦੇ ਪ੍ਰਸਿੱਧ ਮਿਊਜ਼ੀਅਮਾਂ ਵਿੱਚ ਸਿੱਖ ਕਲਾ ਦੀਆਂ ਪ੍ਰਦਰਸ਼ਨੀਆਂ ਲਗਵਾਈਆਂ, ਜਿਸ ਨਾਲ ਪੰਜਾਬੀ ਵਿਰਾਸਤ ਨੂੰ ਨਵੀਂ ਪਛਾਣ ਮਿਲੀ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-144Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
