  ('2030e6ba-84ad-4ca8-afc0-becc4b4af0df', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b75f9224-e0f6-42a8-a3fc-e6749db8a4b1', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਉਹਨਾਂ ਨੇ AIFG ਈ. ਵਿੱਚ ਸਿੱਖ ਆਰਟ ਐਂਡ ਮਿਸ਼ਨਰੀ ਟਰੱਸਟ ਦੀ ਸਥਾਪਨਾ ਕੀਤੀ ਜਿਸ ਰਾਹੀਂ ਸਿੱਖੀ ਨਾਲ ਸੰਬੰਧਤ ਧਾਰਮਿਕ ਅਤੇ ਇਤਿਹਾਸਕ ਵਸਤਾਂ ਜਿਵੇਂ ਚਿੱਤਰ, ਪੇਂਟਿੰਗਜ਼, ਸਿੱਕੇ, ਭਾਂਡੇ ਆਦਿ ਨੂੰ ਸੰਭਾਲਣ ਦੇ ਬੇਸ਼ਕੀਮਤੀ ਯਤਨ ਕੀਤੇ ਗਏ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-144Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('f84ab6e7-e351-4bc5-bee8-faf2b1574826', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b75f9224-e0f6-42a8-a3fc-e6749db8a4b1', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਉਹਨਾਂ ਨੇ ਦੁਨੀਆ ਭਰ ਦੇ ਪ੍ਰਸਿੱਧ ਮਿਊਜ਼ੀਅਮਾਂ ਵਿੱਚ ਸਿੱਖ ਕਲਾ ਦੀਆਂ ਪ੍ਰਦਰਸ਼ਨੀਆਂ ਲਗਵਾਈਆਂ, ਜਿਸ ਨਾਲ ਪੰਜਾਬੀ ਵਿਰਾਸਤ ਨੂੰ ਨਵੀਂ ਪਛਾਣ ਮਿਲੀ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-144Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('a42df064-7f3d-4934-8241-c8199cd9e555', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b75f9224-e0f6-42a8-a3fc-e6749db8a4b1', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਉਹਨਾਂ ਨੇ ਲੰਡਨ ਵਿੱਚ ਰਹਿੰਦਿਆਂ ਸਤਿੰਦਰ ਕੌਰ ਨਾਲ ਵਿਆਹ ਕਰਵਾਇਆ। ਉਹਨਾਂ ਦੀ ਪਤਨੀ ਨੇ ਵੀ ਸਿੱਖ-ਕਲਾ ਤੇ ਸੰਸਕ੍ਰਿਤੀ ਦੇ ਪ੍ਰਸਾਰ ਵਿੱਚ ਉਹਨਾਂ ਦਾ ਭਰਪੂਰ ਸਾਥ ਦਿੱਤਾ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-144Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('b57820b2-ac6b-432f-bbe6-d7ffd8f63756', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b75f9224-e0f6-42a8-a3fc-e6749db8a4b1', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪ੍ਰਸਿੱਧ ਅਮਰੀਕਨ ਵਪਾਰਕ ਰਸਾਲੇ 'ਫੋਰਚੂਨ' ਵੱਲੋਂ 2009 ਈ. ਵਿੱਚ '20ਵੀਂ ਸਦੀ ਦਾ ਛੁਪਿਆ ਨਾਇਕ' ਸਿਰਲੇਖ ਅਧੀਨ ਕਪਾਨੀ ਸਾਹਿਬ ਦੀਆਂ ਪ੍ਰਾਪਤੀਆਂ ਬਾਰੇ ਪ੍ਰਕਾਸ਼ਿਤ ਲੇਖ ਨੇ ਉਹਨਾਂ ਦੇ ਕੱਦ-ਬੁੱਤ ਨੂੰ ਹੋਰ ਬੁਲੰਦੀਆਂ ਬਖਸ਼ੀਆਂ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-144Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('c93c89cb-0159-4c69-9e4f-0e73031de32d', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b75f9224-e0f6-42a8-a3fc-e6749db8a4b1', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$2008 ਈ: ਵਿੱਚ ਉਹਨਾਂ ਨੂੰ ਯੂਨੀਵਰਸਿਟੀ ਆਫ ਕੈਲੀਫੋਰਨੀਆ ਸਾਂਤਾ ਕਰੂਜ਼ ਵਿਗਿਆਨਿਕ ਅਤੇ ਅਕਾਦਮਿਕ ਪ੍ਰਾਪਤੀਆਂ ਲਈ 'ਫੀਅਟ ਲਕਸ ਸਨਮਾਨ' ਨਾਲ ਨਿਵਾਜਿਆ ਗਿਆ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-144Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('323350d0-cc41-43bd-b340-669cb77dc9e5', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b75f9224-e0f6-42a8-a3fc-e6749db8a4b1', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$2011 ਈ. ਵਿੱਚ ਉਹਨਾਂ ਨੂੰ ਅਮਰੀਕਾ ਦੀ ਨੈਸ਼ਨਲ ਇਨਵੈਂਟਰ ਕਾਊਂਸਲ ਦੇ ਮੈਂਬਰ ਵਜੋਂ ਨਿਯੁਕਤ ਕੀਤਾ ਗਿਆ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-144Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('efec1ef7-d49c-4215-8803-9a1406720380', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b75f9224-e0f6-42a8-a3fc-e6749db8a4b1', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਪਾਨੀ ਕੇਵਲ ਖੋਜੀ ਹੀ ਨਹੀਂ ਰਹੇ, ਸਗੋਂ ਉਹਨਾਂ ਨੇ ਆਪਣੀ ਖੋਜ ਨੂੰ ਸਮਾਜ ਤੱਕ ਪਹੁੰਚਾਉਣ ਲਈ ਅਹਿਮ ਕਦਮ ਚੁੱਕੇ। ਉਹਨਾਂ ਨੇ ਸਟੈਨਫੋਰਡ ਯੂਨੀਵਰਸਿਟੀ ਅਤੇ ਯੂਨੀਵਰਸਿਟੀ ਆਫ ਕੈਲੀਫੋਰਨੀਆ ਸਾਂਤਾ ਕਰੂਜ਼ ਵਿੱਚ ਵਿਦਿਆਰਥੀਆਂ ਨੂੰ ਪੜ੍ਹਾਇਆ ਅਤੇ ਖੋਜ ਸੰਸਥਾਵਾਂ ਸਥਾਪਿਤ ਕੀਤੀਆਂ। ਉਹਨਾਂ ਨੇ ਕਈ ਹਾਈ-ਟੈੱਕ ਕੰਪਨੀਆਂ ਸਥਾਪਿਤ ਕੀਤੀਆਂ ਜੋ ਫਾਈਬਰ ਆਪਟਿਕਸ ਦੀ ਵਰਤੋਂ ਨੂੰ ਵਪਾਰਕ ਜਗਤ ਵਿੱਚ ਲੈ ਕੇ ਆਈਆਂ। ਉਹ ਆਪਟੀਕਲ ਸੋਸਾਇਟੀ ਆਫ ਅਮਰੀਕਾ, ਬ੍ਰਿਟਿਸ਼ ਰੋਇਲ ਅਕੈਡਮੀ ਆਫ ਇੰਜੀਨੀਅਰਿੰਗ, ਅਮਰੀਕਨ ਐਸੋਸੀਏਸ਼ਨ ਫਾਰ ਐਡਵਾਂਸਮੈਂਟ ਆਫ ਸਾਇੰਸ ਵਰਗੀਆਂ ਸੰਸਥਾਵਾਂ ਦੇ ਮੈਂਬਰ ਰਹੇ। ਨਰਿੰਦਰ ਸਿੰਘ ਕਪਾਨੀ ਵਿਗਿਆਨ ਦੇ ਨਾਲ-ਨਾਲ ਆਪਣੀਆਂ ਧਾਰਮਿਕ ਅਤੇ ਸੱਭਿਆਚਾਰਕ ਜੜ੍ਹਾਂ ਨਾਲ ਵੀ ਡੂੰਘੇ ਜੁੜੇ ਰਹੇ। ਉਹਨਾਂ ਨੇ AIFG ਈ. ਵਿੱਚ ਸਿੱਖ ਆਰਟ ਐਂਡ ਮਿਸ਼ਨਰੀ ਟਰੱਸਟ ਦੀ ਸਥਾਪਨਾ ਕੀਤੀ ਜਿਸ ਰਾਹੀਂ ਸਿੱਖੀ ਨਾਲ ਸੰਬੰਧਤ ਧਾਰਮਿਕ ਅਤੇ ਇਤਿਹਾਸਕ ਵਸਤਾਂ ਜਿਵੇਂ ਚਿੱਤਰ, ਪੇਂਟਿੰਗਜ਼, ਸਿੱਕੇ, ਭਾਂਡੇ ਆਦਿ ਨੂੰ ਸੰਭਾਲਣ ਦੇ ਬੇਸ਼ਕੀਮਤੀ ਯਤਨ ਕੀਤੇ ਗਏ। ਉਹਨਾਂ ਨੇ ਦੁਨੀਆ ਭਰ ਦੇ ਪ੍ਰਸਿੱਧ ਮਿਊਜ਼ੀਅਮਾਂ ਵਿੱਚ ਸਿੱਖ ਕਲਾ ਦੀਆਂ ਪ੍ਰਦਰਸ਼ਨੀਆਂ ਲਗਵਾਈਆਂ, ਜਿਸ ਨਾਲ ਪੰਜਾਬੀ ਵਿਰਾਸਤ ਨੂੰ ਨਵੀਂ ਪਛਾਣ ਮਿਲੀ। ਵਿਗਿਆਨਿਕ ਖੋਜਾਂ ਦੇ ਨਾਲ ਧਾਰਮਿਕ ਵਿਰਾਸਤ ਨੂੰ ਜਿਊਂਦਾ ਰੱਖਣ ਦੇ ਉਪਰਾਲਿਆਂ ਨੂੰ ਜਾਰੀ ਰੱਖਣਾ ਉਹਨਾਂ ਦੀ ਸ਼ਖਸੀਅਤ ਦਾ ਵਿਲੱਖਣ ਪਹਿਲੂ ਹੀ ਕਿਹਾ ਜਾ ਸਕਦਾ ਹੈ। ਉਹਨਾਂ ਨੇ ਲੰਡਨ ਵਿੱਚ ਰਹਿੰਦਿਆਂ ਸਤਿੰਦਰ ਕੌਰ ਨਾਲ ਵਿਆਹ ਕਰਵਾਇਆ। ਉਹਨਾਂ ਦੀ ਪਤਨੀ ਨੇ ਵੀ ਸਿੱਖ-ਕਲਾ ਤੇ ਸੰਸਕ੍ਰਿਤੀ ਦੇ ਪ੍ਰਸਾਰ ਵਿੱਚ ਉਹਨਾਂ ਦਾ ਭਰਪੂਰ ਸਾਥ ਦਿੱਤਾ। ਪ੍ਰਸਿੱਧ ਅਮਰੀਕਨ ਵਪਾਰਕ ਰਸਾਲੇ 'ਫੋਰਚੂਨ' ਵੱਲੋਂ 2009 ਈ. ਵਿੱਚ '20ਵੀਂ ਸਦੀ ਦਾ ਛੁਪਿਆ ਨਾਇਕ' ਸਿਰਲੇਖ ਅਧੀਨ ਕਪਾਨੀ ਸਾਹਿਬ ਦੀਆਂ ਪ੍ਰਾਪਤੀਆਂ ਬਾਰੇ ਪ੍ਰਕਾਸ਼ਿਤ ਲੇਖ ਨੇ ਉਹਨਾਂ ਦੇ ਕੱਦ-ਬੁੱਤ ਨੂੰ ਹੋਰ ਬੁਲੰਦੀਆਂ ਬਖਸ਼ੀਆਂ। ਉਹਨਾਂ ਦੀਆਂ ਸੇਵਾਵਾਂ ਨੂੰ ਵਿਸ਼ਵ ਪੱਧਰ 'ਤੇ ਸਵੀਕਾਰਿਆ ਗਿਆ। 2008 ਈ: ਵਿੱਚ ਉਹਨਾਂ ਨੂੰ ਯੂਨੀਵਰਸਿਟੀ ਆਫ ਕੈਲੀਫੋਰਨੀਆ ਸਾਂਤਾ ਕਰੂਜ਼ ਵਿਗਿਆਨਿਕ ਅਤੇ ਅਕਾਦਮਿਕ ਪ੍ਰਾਪਤੀਆਂ ਲਈ 'ਫੀਅਟ ਲਕਸ ਸਨਮਾਨ' ਨਾਲ ਨਿਵਾਜਿਆ ਗਿਆ। 2011 ਈ. ਵਿੱਚ ਉਹਨਾਂ ਨੂੰ ਅਮਰੀਕਾ ਦੀ ਨੈਸ਼ਨਲ ਇਨਵੈਂਟਰ ਕਾਊਂਸਲ ਦੇ ਮੈਂਬਰ ਵਜੋਂ ਨਿਯੁਕਤ ਕੀਤਾ ਗਿਆ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-144Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL);
